// Writes the MCP Apps App bundle into a TypeScript module so the story card never reads files at runtime
// (Vercel's function bundle couldn't: EBADF). Runs on npm install (postinstall). Output is git-ignored.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const source = readFileSync(require.resolve("@modelcontextprotocol/ext-apps/app-with-deps"), "utf8");
mkdirSync("src/generated", { recursive: true });
writeFileSync("src/generated/ext-apps-bundle.ts", `// Generated by scripts/embed-app-bundle.mjs. Do not edit.\nexport const EXT_APPS_BUNDLE = ${JSON.stringify(source)};\n`);
console.log(`embedded @modelcontextprotocol/ext-apps app bundle (${source.length} chars)`);
